export function makeCommercialCase({updated=false,workspace=workspaceRef,unavailable=[],addConflict=false}={}){
 const documents=(updated?[...original,rev3]:original).map(d=>({...d,workspaceRef:workspace}));
 if(addConflict)documents.push({...doc('doc:conflicting-decision','2026-11-11T15:00:00Z',
  'accepted','decision',['advance'],[
  '# Дополнительное решение','Аванс: 45% от суммы с НДС.','Подписант утверждает другой порядок оплаты.']),
  workspaceRef:workspace});
 const revision=updated?'workspace:2':addConflict?'workspace:3':'workspace:1';
 const allowedSources=documents.map(d=>d.sourceRef);
 let reads=0,lists=0;
 const sourcePort={
  async listSources(){lists++;return {scopeRevision:revision,
   sources:documents.map(({content,...meta})=>meta).reverse()};},
  async readSource({sourceRef}){reads++;
   const found=documents.find(d=>d.sourceRef===sourceRef);
   if(!found||unavailable.includes(sourceRef))return {revision:'unavailable',complete:false};
   return {revision:found.revision,complete:true,content:found.content};}
 };
 return {request:{taskId:'task:renew-warehouse-control-offer',workspaceRef:workspace,
  scopeRevision:revision,maxTokens:2100,allowedSources,fields},sourcePort,documents,
  getMetrics:()=>({reads,lists})};
}
